import math

def E(n):
    if n < 0:
        return None
    # Handle 2n-1 = -1 case for n=0 separately, although 2n-1 is not composite here
    denominator = 2 * n - 1
    if denominator == 0:
        return None # Should not happen for integer n

    try:
        # Calculate (n+2)! + 1
        numerator_term = math.factorial(n + 2) + 1

        # Calculate E(n)
        value = 3 * numerator_term / denominator
        return value
    except OverflowError:
        return float('inf')

# Test composite denominators: 9, 15, 21, 25, 27
# Corresponds to n = 5, 8, 11, 13, 14
composite_n = [5, 8, 11, 13, 14]
results = {}

for n in composite_n:
    val = E(n)
    is_integer = val == int(val) if val is not None and val != float('inf') else False
    results[n] = {'value': val, 'is_integer': is_integer}

print("Results for composite denominators (n=5, 8, 11, 13, 14):")
for n, res in results.items():
    print(f"n={n}, 2n-1={2*n-1}: Integer={res['is_integer']}")

